import type { BillingStoreData, Customer, Garment, Order, Service } from "./types";

function makePrices(service: Service, price: number): Record<Service, number> {
  return {
    "Dry Cleaning": service === "Dry Cleaning" ? price : 0,
    Ironing: service === "Ironing" ? price : 0,
    "Shoe Cleaning": service === "Shoe Cleaning" ? price : 0,
    Household: service === "Household" ? price : 0,
    Laundry: service === "Laundry" ? price : 0,
  };
}

